azg_storage_state.definition:
CREATE TABLE public.azg_storage_state (
    id smallint NOT NULL,
    schema json NOT NULL,
    CONSTRAINT azg_ss_singleton CHECK ((id = 1))
);

azg_subject_revisions.definition:
CREATE TABLE public.azg_subject_revisions (
    panel character varying(64) NOT NULL COLLATE pg_catalog."C",
    subject_type character varying(128) NOT NULL COLLATE pg_catalog."C",
    subject_id character varying(64) NOT NULL COLLATE pg_catalog."C",
    revision bigint DEFAULT '0'::bigint NOT NULL
);

cache.definition:
CREATE TABLE public.cache (
    key character varying(255) NOT NULL,
    value text NOT NULL,
    expiration integer NOT NULL
);

cache_locks.definition:
CREATE TABLE public.cache_locks (
    key character varying(255) NOT NULL,
    owner character varying(255) NOT NULL,
    expiration integer NOT NULL
);

migrations.definition:
CREATE TABLE public.migrations (
    id integer NOT NULL,
    migration character varying(255) NOT NULL,
    batch integer NOT NULL
);

password_reset_tokens.definition:
CREATE TABLE public.password_reset_tokens (
    email character varying(255) NOT NULL,
    token character varying(255) NOT NULL,
    created_at timestamp(0) without time zone
);

prc_network_permit_scopes.definition:
CREATE TABLE public.prc_network_permit_scopes (
    permit_id uuid NOT NULL,
    budget_id uuid NOT NULL
);

prc_network_route_profile_members.definition:
CREATE TABLE public.prc_network_route_profile_members (
    profile_id uuid NOT NULL,
    route_id uuid NOT NULL
);

prc_network_route_profiles.definition:
CREATE TABLE public.prc_network_route_profiles (
    id uuid NOT NULL,
    profile_key text NOT NULL,
    policy_version bigint NOT NULL,
    CONSTRAINT prc_network_route_profiles_policy_version_check CHECK ((policy_version >= 1))
);

prc_outbound_operation_controls.definition:
CREATE TABLE public.prc_outbound_operation_controls (
    operation_id uuid NOT NULL,
    control_scope_id uuid NOT NULL,
    control_version bigint NOT NULL
);

prc_process_projection_receipts.definition:
CREATE TABLE public.prc_process_projection_receipts (
    projector_key text NOT NULL,
    event_id uuid NOT NULL,
    applied_at timestamp with time zone NOT NULL
);

prc_procurement_documents.definition:
CREATE TABLE public.prc_procurement_documents (
    procurement_id bigint NOT NULL,
    document_id bigint NOT NULL,
    observed_at timestamp(6) with time zone NOT NULL,
    removed_at timestamp(6) with time zone
);

prc_proxyma_endpoint_links.definition:
CREATE TABLE public.prc_proxyma_endpoint_links (
    proxy_id bigint NOT NULL,
    tenant_key text NOT NULL,
    endpoint_id uuid NOT NULL
);
